"""Emit the small finite sign/permutation action proof for the D8 base.

Only the 128 seven-bit sign choices and seven adjacent exchanges are
expanded.  The normal-form table itself remains a symbolic finite schema.
"""
from itertools import product
from pathlib import Path


HEADER = '''------------------------------------------------------------------------
-- Presentations of groups
--
-- Exact vector action of the finite even-signed-permutation sections.
-- Generated by ThreeQubit/build_stabilizer.py.
------------------------------------------------------------------------

{-# OPTIONS --without-K --safe #-}

module Examples.Groups.CCX+HH.ThreeQubit.StabilizerAction where

open import Data.Bool.Base using (Bool ; false ; true ; not)
open import Data.Fin.Base using (Fin)
open import Data.Nat.Base using (ℕ ; zero ; suc)
open import Data.Vec.Base using (Vec ; [] ; _∷_ ; lookup ; tabulate ; zipWith)
import Data.Vec.Properties as VP
open import Word.Base using (Word ; [_]ʷ ; ε ; _•_ ; _ʷ ; wmap)
open import Relation.Binary.PropositionalEquality as Eq using (_≡_ ; refl)
import Examples.Groups.Symmetric.Syntactics as P
import Examples.Groups.Symmetric.SubPresentation.Semantics as PS
import Examples.Groups.CCX+HH-TwoLevel.Semantics as S
open import Examples.Groups.CCX+HH-TwoLevel.Ring using (D ; -ᴰ_ ; module DS)
open import Examples.Groups.CCX+HH.ThreeQubit.StabilizerGenerators using (Letter ; b ; exchange)
open import Examples.Groups.CCX+HH.ThreeQubit.StabilizerNormalForm
  using (phase-word ; position ; parity)
open S using (actV ; set₁ ; set₂)

neg : Bool → D → D
neg false x = x
neg true x = -ᴰ x

apply : ∀ {n} → Vec Bool n → Vec D n → Vec D n
apply = zipWith neg

neg-double : ∀ x → -ᴰ (-ᴰ x) ≡ x
neg-double = DS.solve 1 (λ x → DS._:=_ (DS.:-_ (DS.:-_ x)) x) refl

neg-not : ∀ a x → neg (not a) x ≡ -ᴰ (neg a x)
neg-not false x = refl
neg-not true x = Eq.sym (neg-double x)

private
  neg-power : ℕ → D → D
  neg-power zero x = x
  neg-power (suc n) x = -ᴰ (neg-power n x)

  odd : ℕ → Bool
  odd zero = false
  odd (suc n) = not (odd n)

  power-correct : ∀ n x → neg-power n x ≡ neg (odd n) x
  power-correct zero x = refl
  power-correct (suc n) x = Eq.trans (Eq.cong -ᴰ_ (power-correct n x))
    (Eq.sym (neg-not (odd n) x))

opaque
  unfolding actV set₁ set₂

  phases : ∀ s v → S.actVʷ ((b ʷ) (phase-word (λ i → i) s)) v ≡
    apply (parity s ∷ s) v
'''


def vec(xs):
    return ' ∷ '.join([*xs, '[]'])


def build():
    lines = [HEADER]
    values = list('abcdefgh')
    vector = '(' + vec(values) + ')'
    for bits in product((False, True), repeat=7):
        signs = ['true' if bit else 'false' for bit in bits]
        out = ['-ᴰ ' + v if bit else v for bit, v in zip(bits, values[1:])]
        out = ['(' + v + ')' if v.startswith('-') else v for v in out]
        lines.append(f'  phases ({vec(signs)}) {vector} =\n'
                     f'    Eq.cong (λ x → {vec(["x", *out])}) (power-correct {sum(bits)} a)\n')
    lines.append('''
  permutation-gen : ∀ (g : P.Gen 8) v →
    S.actVʷ (b (exchange (position g))) v ≡ tabulate (λ i → lookup v (PS.⟦ g ⟧ᵍ i))
''')
    for i in range(7):
        gate = 'P.gate₂ P.σ-gate'
        for _ in range(i):
            gate = f'({gate}) P.↥'
        lines.append(f'  permutation-gen ({gate}) {vector} = refl\n')
    # The shifted width-one alphabet is empty.  The absurd pattern in
    # gate₁ covers that final constructor; gate₀ is handled separately.
    empty = 'P.gate₁ ()'
    for _ in range(7):
        empty = f'({empty}) P.↥'
    lines.append(f'  permutation-gen ({empty}) v\n')
    empty = 'P.gate₀ ()'
    for _ in range(8):
        empty = f'({empty}) P.↥'
    lines.append(f'  permutation-gen ({empty}) v\n')
    lines.append('''
permutation-action : ∀ (w : P.Circuit 8) v i →
  lookup (S.actVʷ ((b ʷ) (wmap (λ g → exchange (position g)) w)) v) i ≡
  lookup v (PS.⟦ w ⟧ i)
permutation-action [ g ]ʷ v i = Eq.trans
  (Eq.cong (λ z → lookup z i) (permutation-gen g v))
  (VP.lookup∘tabulate (λ j → lookup v (PS.⟦ g ⟧ᵍ j)) i)
permutation-action ε v i = refl
permutation-action (u • w) v i = Eq.trans
  (permutation-action u (S.actVʷ ((b ʷ) (wmap (λ g → exchange (position g)) w)) v) i)
  (permutation-action w v (PS.⟦ u ⟧ i))
''')
    return ''.join(lines)


if __name__ == '__main__':
    import argparse
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true',
                        help='compare the generated module without writing it')
    args = parser.parse_args()
    path = Path(__file__).with_name('StabilizerAction.agda')
    expected = build()
    if args.check:
        assert path.read_text(encoding='utf8') == expected, 'StabilizerAction.agda is stale'
        print('Verified 128 sign sections and seven permutation generators.')
    else:
        path.write_text(expected, encoding='utf8')
